function _validateSingleCall(bytes calldata _callData, address sessionKeySigner) internal view returns (bool) {
        (address target,, bytes calldata execData) = ExecutionLib.decodeSingle(_callData[EXEC_OFFSET:]);
        bytes4 selector = _validateSelector(bytes4(execData[0:4]));
        if (selector == bytes4(0)) return false;
        if (selector == IERC20.approve.selector) return true;
        if (selector == CredibleAccountModule.claim.selector) {
            // Ensure the session key signer matches the expected session key
            require(sessionKeySigner == msg.sender, "Invalid session key signer");
            return true;
        }
        if (target != address(this)) return false; // If not approve call must call this contract
        return true;
    }

